        /* =====================================================
           AI - SCADA RESPONSE
           ===================================================== */

        buildSCADAResponse: function() {

            var html =
                "<strong>Latest SCADA Reading</strong>" +
                "<br /><br />";


            var gr =
                new GlideRecord(
                    this.SENSOR_TABLE
                );


            gr.orderByDesc(
                "sys_created_on"
            );

            gr.setLimit(1);

            gr.query();


            if (
                !gr.next()
            ) {

                return (
                    html +
                    "No SCADA sensor reading was found."
                );

            }


            html +=
                "<div style='padding:10px;border:1px solid #e2e8f0;border-radius:8px;background:#ffffff;'>";


            html +=
                "<strong>Pressure:</strong> " +
                this.getDisplay(
                    gr,
                    "pressure"
                );


            html +=
                "<br /><strong>Temperature:</strong> " +
                this.getDisplay(
                    gr,
                    "temperature"
                );


            html +=
                "<br /><strong>Flow Rate:</strong> " +
                this.getDisplay(
                    gr,
                    "flow_rate"
                );


            html +=
                "<br /><strong>Sensor Status:</strong> " +
                this.getDisplay(
                    gr,
                    "sensor_status"
                );


            html +=
                "<br /><strong>Updated:</strong> " +
                this.getDisplay(
                    gr,
                    "sys_created_on"
                );


            html +=
                "</div>";


            return html;

        },


        /* =====================================================
           TYPE
           ===================================================== */

        type:
            "SentinelHSEDashboardAjax"

    }
);
